style.css:
/* =========================================
   VS Code Teal/Lime Theme — Neutral Emphasis Edition
   - No orange bold
   - No pink bold
   - Clean gold-neutral emphasis
   - Keeps sidebar/project icon colors intact
   ========================================= */

:root {
  /* Base */
  --background-color: #2B2B2B;
  --text-color: #EFEAE2; /* slightly brighter main text */
  --muted-text: rgba(239, 234, 226, 0.86);

  /* Editor-style accents */
  --teal: #24B8B3;
  --lime: #B9D84A;
  --green: #7ACB72;
  --gold: #E6C07B;
  --neutral-bold: #F2E6C9; /* NEW: refined bold (soft gold-neutral) */
  --neutral: #CFC7BC;
}

/* Background + base readability */
body {
  background-color: var(--background-color) !important;
  color: var(--text-color) !important;
}

/* Long text slightly softer for hierarchy */
p, li {
  color: var(--muted-text) !important;
}

/* ===== BOLD (refined: readable, not flashy) ===== */
strong {
  color:#E57373 !important;
  font-weight: 700 !important;
}

/* Italics = teal (matches editor vibe) */
em {
  color: var(--teal) !important;
  font-style: italic !important;
}

/* Prevent color conflicts inside headings */
h1 strong, h1 em,
h2 strong, h2 em,
h3 strong, h3 em,
h4 strong, h4 em,
h5 strong, h5 em,
h6 strong, h6 em {
  color: inherit !important;
}

/* Headings (clean editor hierarchy) */
h1 { color: var(--teal) !important; }
h2 { color: var(--green) !important; }
h3 { color: var(--lime) !important; }
h4 { color: var(--gold) !important; }
h5 { color: #D9C7A1 !important; }
h6 { color: var(--neutral) !important; }

/* Links (no blue UI, no sidebar underlines) */
a {
  text-decoration: none !important;
}

main a, article a {
  color: var(--teal) !important;
}

main a:hover, article a:hover {
  color: var(--lime) !important;
  text-decoration: underline !important;
  text-underline-offset: 3px !important;
  text-decoration-color: rgba(185, 216, 74, 0.45) !important;
}

/* Code blocks (VS Code feel) */
code {
  color: var(--lime) !important;
  background: rgba(0, 0, 0, 0.25) !important;
  border: 1px solid rgba(255, 255, 255, 0.06) !important;
  border-radius: 6px !important;
  padding: 0.12em 0.35em !important;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace !important;
}

pre {
  color: var(--gold) !important;
  background: rgba(0, 0, 0, 0.35) !important;
  border-left: 3px solid rgba(36, 184, 179, 0.55) !important;
  border-radius: 12px !important;
  padding: 14px !important;
  overflow: auto !important;
}

/* Blockquotes (subtle structure cue) */
blockquote {
  border-left: 3px solid rgba(36, 184, 179, 0.55) !important;
  background: rgba(0, 0, 0, 0.18) !important;
  border-radius: 10px !important;
  padding: 10px 14px !important;
  color: rgba(239, 234, 226, 0.92) !important;
}

/* Selection (no blue flash) */
::selection {
  background: rgba(36, 184, 179, 0.30) !important;
  color: #FFFFFF !important;
}
